import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np
    from scipy import stats

    df_ob = df[df['row_kind'] == 'on_book'].copy()
    df_ob['snapshot_date'] = pd.to_datetime(df_ob['snapshot_date'])

    # Latest snapshot per account (on_book)
    latest = df_ob.sort_values('snapshot_date').groupby('account_id').last().reset_index()

    # EDA on all rows (as loaded)
    for col in ['balance', 'deposits']:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception as e:
    result['assumptions'].append(f"EDA error: {e}")

# Segmentation
try:
    for seg_col in ['segment', 'branch']:
        for metric, agg in [('balance', 'sum'), ('deposits', 'sum')]:
            grp = latest.groupby(seg_col)[metric].sum().nlargest(10)
            result['segments'].append({
                'segment_column': seg_col,
                'metric_column': metric,
                'aggregation': 'sum',
                'label': None,
                'results': [{'name': str(k), 'value': float(v)} for k, v in grp.items()]
            })
        # open accounts count
        cnt = latest.groupby(seg_col)['account_id'].count().nlargest(10)
        result['segments'].append({
            'segment_column': seg_col,
            'metric_column': 'account_id',
            'aggregation': 'count',
            'label': 'open_accounts',
            'results': [{'name': str(k), 'value': float(v)} for k, v in cnt.items()]
        })
        # avg balance per account
        avg = latest.groupby(seg_col).apply(lambda x: x['balance'].sum() / x['account_id'].nunique()).nlargest(10)
        result['segments'].append({
            'segment_column': seg_col,
            'metric_column': 'balance',
            'aggregation': 'ratio',
            'label': 'avg_balance_per_account',
            'results': [{'name': str(k), 'value': float(v)} for k, v in avg.items()]
        })
except Exception as e:
    result['assumptions'].append(f"Segmentation error: {e}")

# Correlations (one row per account, latest snapshot)
try:
    num_cols = ['balance', 'deposits']
    corr_df = latest[num_cols].dropna()
    for i, c1 in enumerate(num_cols):
        for c2 in num_cols[i+1:]:
            r = corr_df[c1].corr(corr_df[c2])
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception as e:
    result['assumptions'].append(f"Correlation error: {e}")

# Trends (weekly, on_book rows, latest per account per week)
try:
    df_ob2 = df_ob.copy()
    df_ob2['week'] = df_ob2['snapshot_date'].dt.to_period('W')
    # Latest per account per week
    weekly_latest = df_ob2.sort_values('snapshot_date').groupby(['account_id', 'week']).last().reset_index()
    weekly_bal = weekly_latest.groupby('week')['balance'].sum()
    weekly_dep = weekly_latest.groupby('week')['deposits'].sum()

    for col, series in [('balance', weekly_bal), ('deposits', weekly_dep)]:
        if len(series) >= 2:
            pct = float((series.iloc[-1] - series.iloc[-2]) / series.iloc[-2] * 100) if series.iloc[-2] != 0 else 0.0
            direction = 'up' if pct > 0.5 else ('down' if pct < -0.5 else 'flat')
            result['trends'].append({
                'column': col, 'period': '7d_rolling',
                'direction': direction, 'pct_change': round(pct, 4), 'segment': None
            })
except Exception as e:
    result['assumptions'].append(f"Trend error: {e}")

# Anomalies (IQR, on all rows as loaded)
try:
    anomaly_count = 0
    for col in ['balance', 'deposits']:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1)
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_t, hi_t = q1 - 3 * iqr, q3 + 3 * iqr
        mask = (s_t < lo_t) | (s_t > hi_t)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are natural for this distribution'
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_t) - shift)
            hi_orig = float(np.expm1(hi_t) - shift)
        else:
            lo_orig, hi_orig = float(lo_t), float(hi_t)
        exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
        flagged = df.loc[mask[mask].index]
        for idx, row in flagged.iterrows():
            if anomaly_count >= 25:
                break
            val = float(row[col])
            if abs(skew) > 2:
                val_t = float(np.log1p(val + shift))
            else:
                val_t = val
            if val_t > q3 + 5 * iqr or val_t < q1 - 5 * iqr:
                sev = 'critical'
            elif val_t > q3 + 4 * iqr or val_t < q1 - 4 * iqr:
                sev = 'high'
            else:
                sev = 'medium'
            result['anomalies'].append({
                'column': col, 'row_index': int(idx), 'value': val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {val:.2f} lies outside expected range {exp_range}'
            })
            anomaly_count += 1
except Exception as e:
    result['assumptions'].append(f"Anomaly error: {e}")

# Forecasting (simple linear extrapolation on weekly balance)
try:
    df_ob3 = df_ob.copy()
    df_ob3['week'] = df_ob3['snapshot_date'].dt.to_period('W')
    wl = df_ob3.sort_values('snapshot_date').groupby(['account_id', 'week']).last().reset_index()
    wb = wl.groupby('week')['balance'].sum().reset_index()
    wb['week_num'] = range(len(wb))
    if len(wb) >= 3:
        slope, intercept, _, _, _ = stats.linregress(wb['week_num'], wb['balance'])
        next_wn = len(wb)
        next2_wn = len(wb) + 1
        last_period = wb['week'].iloc[-1]
        fp1 = float(intercept + slope * next_wn)
        fp2 = float(intercept + slope * next2_wn)
        result['forecast_points'].append({'period': f'week+1 after {last_period}', 'value': round(fp1, 2)})
        result['forecast_points'].append({'period': f'week+2 after {last_period}', 'value': round(fp2, 2)})
except Exception as e:
    result['assumptions'].append(f"Forecast error: {e}")

result['assumptions'] += [
    "balance is a level: summed over latest on_book snapshot per account per period",
    "deposits summed over on_book rows only",
    "correlations computed on one row per account (latest on_book snapshot)",
    "anomaly detection uses all loaded rows (as-loaded per EDA spec)"
]

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

try:
    _head_df = df.head(5).replace({float('nan'): None})
    result['head_preview'] = _head_df.to_dict('records')
except Exception:
    pass

try:
    result['dtypes_summary'] = {str(k): str(v) for k, v in df.dtypes.items()}
    result['non_null'] = {str(k): int(v) for k, v in df.notna().sum().items()}
    result['n_rows'] = int(len(df))
except Exception:
    pass

try:
    _miss = df.isna().mean() * 100
    result['missing_pct'] = {str(k): round(float(v), 2) for k, v in _miss.items()}
except Exception:
    pass

try:
    if 'balance' in df.columns and pd.api.types.is_numeric_dtype(df['balance']):
        _s = df['balance'].dropna()
        if len(_s) > 0 and 'balance' not in result['eda_summary']:
            result['eda_summary']['balance'] = {
                'mean': round(float(_s.mean()), 4),
                'std': round(float(_s.std()), 4),
                'min': round(float(_s.min()), 4),
                'max': round(float(_s.max()), 4),
                'median': round(float(_s.median()), 4),
                'count': int(_s.count()),
            }
except Exception:
    pass

try:
    if 'deposits' in df.columns and pd.api.types.is_numeric_dtype(df['deposits']):
        _s = df['deposits'].dropna()
        if len(_s) > 0 and 'deposits' not in result['eda_summary']:
            result['eda_summary']['deposits'] = {
                'mean': round(float(_s.mean()), 4),
                'std': round(float(_s.std()), 4),
                'min': round(float(_s.min()), 4),
                'max': round(float(_s.max()), 4),
                'median': round(float(_s.median()), 4),
                'count': int(_s.count()),
            }
except Exception:
    pass

try:
    if 'balance' in df.columns and pd.api.types.is_numeric_dtype(df['balance']):
        _col_data = df['balance'].dropna()
        if len(_col_data) >= 5:
            _n_bins = min(10, max(2, _col_data.nunique()))
            _bins = pd.cut(_col_data, bins=_n_bins)
            _vc = _bins.value_counts().sort_index()
            result['distributions']['balance'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items() if _v > 0
            ]
except Exception:
    pass

try:
    if 'deposits' in df.columns and pd.api.types.is_numeric_dtype(df['deposits']):
        _col_data = df['deposits'].dropna()
        if len(_col_data) >= 5:
            _n_bins = min(10, max(2, _col_data.nunique()))
            _bins = pd.cut(_col_data, bins=_n_bins)
            _vc = _bins.value_counts().sort_index()
            result['distributions']['deposits'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items() if _v > 0
            ]
except Exception:
    pass

try:
    if 'segment' in df.columns:
        _vc = df['segment'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['segment'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
