try:
    anomaly_records = []
    for col in ['Amount', 'Balance After']:
        s = ob[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = max(0, -s.min()) + 1 if s.min() < 0 else 0
        if abs(skew) > 2:
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (vals < lo3) | (vals > hi3)
        frac = mask.sum() / len(vals)
        if frac > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'heavy-tailed; {frac*100:.1f}% flagged',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed ({frac*100:.1f}% of values exceed 3×IQR boundary); not individually flagged'
            })
            continue
        # Convert boundaries back to original space
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = float(lo3), float(hi3)
        flagged = ob.loc[mask, col]
