            tv = float(vals.loc[idx])
            if tv < lo5 or tv > hi5:
                sev = 'critical'
            elif tv < lo4 or tv > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': round(float(val), 4),
                'expected_range': f'[{orig_lo:.2f}, {orig_hi:.2f}]',
                'severity': sev,
                'explanation': f'{col} value {round(float(val),4)} lies outside expected range [{orig_lo:.2f}, {orig_hi:.2f}]'
