    bad_txn_type = ['REVERSAL','REV','REVERSAL CREDIT','REVERSAL DEBIT']

    ob = df[
        (df['row_kind'] == 'on_book') &
        (df['Currency'] == 'USD') &
        (~df['Status'].str.lower().isin(bad_status)) &
        (~df['Transaction Type'].str.upper().isin(bad_txn_type))
    ].copy()

    ob['Posting Date'] = pd.to_datetime(ob['Posting Date'])
    ob['Transaction Date'] = pd.to_datetime(ob['Transaction Date'])
except Exception as e:
    ob = df.copy()

# --- EDA ---
try:
    for col in ['Amount', 'Balance After']:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# --- CORRELATIONS (snapshot: one row per account, latest on_book) ---
try:
    snap = ob.sort_values('Posting Date').groupby('Account ID').last().reset_index()
