            pct = float((series.iloc[-1] - series.iloc[-2]) / abs(series.iloc[-2]) * 100) if series.iloc[-2] != 0 else 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
